  AwakerTalent_122607_TalentDesc_1 = {
    Text = "·每打出 2 張「打擊」茉夏進行追擊，隨機造成 1 次 30% 茉夏攻擊力且視為「打擊」的傷害，每回合最多生效 4 次。"
  },
  AwakerTalent_122607_TalentName_1 = {
    Text = "戲劇性邂逅"
  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] ％，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·所有喚醒體觸發中毒效果提高 [Arg3]％ 。\n·每層「痴醉」額外使「人型」敵人造成的傷害降低  1％，移除時額外對「人型」敵人造成 1％ 最大生命值純粹傷害。"
  },
