  AwakerTalent_127223_TalentDesc_1 = {
    Text = "·阿拉克涅在隊伍中時，將替換「超維」界域為「奇點·超維」界域。\n·維度穿梭：每回合首次打出指令卡後觸發該效果，將其臨時原始複製置入超維空間並為其和臨時複製賦予 25 層「奇點信標」，超維回合無法發動該效果。\n·奇點信標：每擁有 1 層使該卡牌造成的傷害、固定力量和觸腕傷害提高、固定中毒、固定反擊最終效果提高 2%，固定護盾、固定生命回覆、力量降低的最終效果提高 1%，打出後移除。擁有奇點信標的卡牌無法觸發「維度穿梭」。\n·超維空間：超維空間達到上限時回合結束改為發動超維空間：不再獲得額外回合，棄掉非保留手牌並觸發虛無效果、將超維空間所有卡牌置入手中，將當前算力設置為 5 點。發動超維空間後，本回合視為超維回合。\n·「奇點湮滅」：取出超維空間最左側的卡牌。3 回合冷卻。\n·探索開始後隊伍傷害強效 +50%，並獲得 15 層「奇點稜鏡」。\n·「奇點稜鏡」：所有指令卡視為擁有等量奇點信標的加成。\n·超維精通：隊伍每有 1 點界域精通，使「奇點稜鏡」和「維度穿梭」施加的「奇點信標」層數提高 0.05％。\n·至純超維：如果隊伍僅由超維或混沌喚醒體組成，超維精通效果和界域提供的傷害強效翻倍。"
  },
