  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] %，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·「無邊荒影」造成力量降低效果、獲得的力量倍率提高  [Arg3]%，每次生效使下次「染罪槍鋒」額外享受 [Arg4]% 力量加成，上限 1200%。"
