  AwakerTalent_130919_TalentDesc_1 = {
    Text = "·該角色在隊伍中時，將替換「深海」界域為「晦暝•深海」界域。\n·基礎觸腕傷害變更為隊伍最大生命值的 5％。\n·探索開始後隊伍傷害強效+50％，如果隊伍僅由深海或混沌喚醒體組成，該效果獲得的傷害強效翻倍，但戰鬥開始不再獲得額外觸腕。\n·不再擁有「觸腕集結」效果。\n·觸腕姿態變更為「晦暝·觸腕姿態」。\n·「晦暝·靜海」：獲得 25％ 最大生命值的護盾，回合結束後觸腕不再攻擊，3 回合冷卻。\n·「晦暝·怒濤」：使本回合觸腕傷害變成 125％，造成主動傷害後使 1 條觸腕攻擊，但回合結束後失去 1 條觸腕，3 回合冷卻。\n·界域精通變更為「晦暝·深海精通」，每點界域精通使「晦暝·靜海」的護盾提升 0.025％ 最大生命值，使「晦暝·怒濤」的觸腕傷害額外提高 0.025％。\n·如果隊伍僅由深海或混沌喚醒體組成，「晦暝·界域精通」效果翻倍。"
  },
  AwakerTalent_130920_TalentDesc_1 = {
    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] ％，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·「渦！流！彈！」固定傷害提高 [Arg3]％。\n·莫絲釋放狂氣爆發前移除目標「加固」與「臨時加固」效果，若成功移除，本次狂氣爆發暴擊傷害 + [Arg4]％。"
  },
