  AwakerTalent_131854_TalentDesc_1 = {
    Text = "·沙耶在隊伍中時，將替換「血肉」界域為「繁育·血肉」界域。\n·胚胎融合：每回合獲得的胚胎融合提高為 50~100，隨損失生命提高，但胚胎融合上限由 100 提高為 200，達到上限時將「繁育·胚胎」置入手中。\n·繁育胚胎：打出時不再獲得暴擊率，吞噬也不再獲得護盾和臨時力量。每名喚醒體每回合首次消耗「繁育·胚胎」時，獲得 40 層「繁育慶典」：每擁有 1 層該喚醒體本回合下次狂氣爆發造成的傷害、固定護盾、固定生命回覆、固定力量、力量降低、觸腕傷害提升、固定中毒、固定反擊的最終效果提高 1％。\n·猩紅熔爐：回合開始的自動積攢量變更為 10% 已損失生命，至多積攢量變更為 50% 最大生命。戰鬥結束時不再積攢，使用時有 3 回合冷卻。\n·猩紅侵蝕：使用猩紅熔爐後對所有敵人造成目標最大生命 1% 的侵蝕，消耗的猩紅熔爐越多侵蝕效果就越強，至多提高 100%。對「空殼」敵人造成 5 倍侵蝕效果。\n·探索開始後，最大生命值提高 10％，隊伍傷害強效 +50%，每回合開始時所有喚醒體獲得 20 層「繁育慶典」。如果隊伍僅由血肉或混沌喚醒體組成，該效果獲得的傷害強效翻倍。\n·界域精通變為「繁育·血肉精通」，每點界域精通使「繁育·血肉」獲得的「繁育慶典」提高 0.05%。 \n·如果隊伍僅由血肉或混沌喚醒體組成，「繁育·血肉精通」效果翻倍。"
  },
  AwakerTalent_131854_TalentName_1 = {
    Text = "繁育淨土"
  },
