  },
  AwakerTalent_145718_TalentDesc_1 = {
    Text = "·卡拉布在隊伍中時，將替換「血肉」界域為「繁育·血肉」界域。\n·胚胎融合：每回合獲得的胚胎融合提高為 50~100，隨損失生命提高，但胚胎融合上限由 100 提高為 200，達到上限時將「繁育·胚胎」置入手中。\n·繁育胚胎：打出時不再獲得暴擊率，吞噬也不再獲得護盾和臨時力量。每名喚醒體每回合首次消耗「繁育·胚胎」時，獲得 40 層「繁育慶典」：每擁有 1 層該喚醒體本回合下次狂氣爆發造成的傷害、固定護盾、固定生命回覆、固定力量、力量降低、觸腕傷害提升、固定中毒、固定反擊的最終效果提高 1％。\n·猩紅熔爐：回合開始的自動積攢量變更為 10% 已損失生命，至多積攢量變更為 50% 最大生命。戰鬥結束時不再積攢，使用時有 3 回合冷卻。\n·猩紅侵蝕：使用猩紅熔爐後對所有敵人造成目標最大生命 1% 的侵蝕，消耗的猩紅熔爐越多侵蝕效果就越強，至多提高 100%。對「空殼」敵人造成 5 倍侵蝕效果。\n·探索開始後，最大生命值提高 10％，隊伍傷害強效 +50%，每回合開始時所有喚醒體獲得 20 層「繁育慶典」。如果隊伍僅由血肉或混沌喚醒體組成，該效果獲得的傷害強效翻倍。\n·界域精通變為「繁育·血肉精通」，每點界域精通使「繁育·血肉」獲得的「繁育慶典」提高 0.05%。 \n·如果隊伍僅由血肉或混沌喚醒體組成，「繁育·血肉精通」效果翻倍。"
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "繁育淨土"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "·蝕滅·蘿坦在隊伍中時，替換「混沌」界域為「原初·混沌」界域。\n·原初灌注：基礎銀鑰能量提高為 2000 點，隊伍傷害強效 +50%，所有喚醒體的攻擊和防禦提高 10%。如果隊伍僅由混沌喚醒體組成，該效果獲得的傷害強效翻倍。戰鬥開始時，獲得 2000 點銀鑰能量。\n·萬鑰同源：所有喚醒體的銀鑰充能等級變為隊伍平均值。且不再根據算力消耗獲得銀鑰能量，而是每名喚醒體每回合首張指令卡獲得「該喚醒體銀鑰充能×3+100」的銀鑰能量。\n·未分之境：不再觸發其他界域的至純界域、精通效果翻倍、強效翻倍效果。\n·原初回響：靈知覺醒獲得預備 1，每回合首次打出時自動釋放攜帶鑰令。\n·記憶碎片：鑰令被替換為「原初·雙生復演」和 「原初·三相天啟」，本身攜帶的鑰令無法釋放。\n·原初 · 雙生復演：從持有鑰令中發現 3 種鑰令，選擇 1 個鑰令使其生效 2 次。\n·原初 · 三相天啟：從持有鑰令中發現 3 組鑰令，每組由 3 種不同鑰令組成，選擇一組使其中鑰令依次生效 1 次。\n·原初·雙生復演和原初·三相天啟中的鑰令會包含八種「原初記憶」。\n·原初·雙生復演和原初·三相天啟僅視為釋放 1 次鑰令，在多次生效時僅對首個生效的鑰令有效。\n·界域精通變為「原初·混沌精通」，每點界域精通使鑰令強度提高 0.05%。\n·每點鑰令強度提高鑰令造成的固定中毒、固定反擊、固定力量、固定觸腕傷害、固定舊日餘燼 2%、提高固定護盾、固定生命回覆、力量降低、暴擊率、暴擊傷害、傷害強效、界域精通、狂氣、胚胎融合、銀鑰能量 1%。\n·如果隊伍僅由混沌喚醒體組成，「原初·混沌精通」效果翻倍。"
  },
