  AwakerTalent_44845_TalentDesc_1 = {
    Text = "·莉莉自身、裝備的命輪與密契每提供 1% 死亡抵抗，「黑沼禁域」與「基礎防禦」的基礎護盾就提高 0.25%，首領戰中忍耐的積攢量和上限提高 0.25%。\n·莉莉在隊伍中時，失去 1 點生命時獲得 1 層忍耐，忍耐堆疊上限等於最大生命。"
  },
