    Text = "·拉蒙娜額外獲得 2.5 點銀鑰充能屬性。每個同調率等級額外使拉蒙娜獲得 0.5 點銀鑰充能屬性。 \n·每擁有 1 點銀鑰充能等級屬性，就使「女王之劍」基礎傷害提高 1 %，打出後獲得 0.75 臨時界域精通。"
