  AwakerTalent_46487_TalentDesc_1 = {
    Text = "·環行·拉蒙娜額外獲得 2.5 點銀鑰充能屬性。每個同調率等級額外使環行·拉蒙娜獲得 0.5 點銀鑰充能屬性。 \n·每擁有 1 點銀鑰充能等級屬性，就使「基礎打擊」的回環效果使環行·拉蒙娜獲得 0.2% 暴擊率，「基礎防禦」的回環效果使環行·拉蒙娜獲得 0.2 狂氣。"
