  AwakerTalent_51744_TalentDesc_1 = {
    Text = "·戰鬥開始時，將 1 張「執妄」置入手中。\n·彌利亞姆的「基礎打擊」享受 100% 觸腕傷害加成。\n·彌利亞姆喚醒體自身、命輪、密契每提供 1% 暴擊傷害，就使狂氣爆發的力量、觸腕傷害、狂氣、施加和觸發中毒效果提高 0.2%。"
