  AwakerTalent_54158_TalentDesc_1 = {
    Text = "·索蕾爾自身、裝備的命輪與密契每有 1% 暴擊率，就使「基礎防禦」獲得的狂氣提高 0.2。"
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "浮華之守"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "·詹金喚醒體自身、命輪、密契每提供 1% 暴擊率，就使「基礎打擊」與「布朗出動」基礎傷害提高 2%。"
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "同仇敵愾"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "·艾瑞卡喚醒體自身、命輪、密契每提供 1  點銀鑰充能等級屬性，「電磁爆破」就使艾瑞卡獲得 0.5% 臨時暴擊率與暴擊傷害。"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "·回合開始時，獲得 1 層夢引。\n·每消耗 1 層夢引，使本場戰鬥中「迷途之守」和「死夢之都」獲得的反擊提高攻擊力的 5%。\n·旺達喚醒體自身、命輪、密契每提供 1% 傷害強效屬性，「死夢之都」獲得的反擊就提高 0.75%。"
  },
  AwakerTalent_55202_TalentName_1 = {Text = "啟示"},
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "·卡茜亞喚醒體自身、命輪、密契每提供 1 點界域精通屬性，「魔術嘉年華」就使卡茜亞所有基礎傷害提高 0.2%。"
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "魔術大師"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "·汀克特喚醒體自身、命輪、密契每提供 1% 黑印掉落屬性，就使「星彩極光」額外獲得 0.15% 臨時暴擊率。"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "·奧爾拉的「基礎打擊」與「基礎防禦」也視為一種詩篇。詩篇躍遷時會切換到不同的情緒，情緒能直接影響此詩篇的效果。處於不同的情緒會帶來不同的隊伍持續效果。\n·奧爾拉每有 1% 死亡抵抗，就使該效果加成提高初始值的 0.1%。"
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "落筆生情"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "·法洛思每擁有 1% 傷害強效屬性，「遺失的久遠之城」造成的護盾就提高 0.4%。"
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "歸鄉執迷"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "·凱刻斯每擁有 1% 黑印掉落屬性，「基礎打擊」就享受 1% 反擊加成。"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "·希萊斯特打出指令卡後激發 1 條觸腕攻擊敵人，希萊斯特自身、命輪、密契每有 1 點界域精通就使本次激發造成 0.5% 觸腕傷害。"
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "遠航號角"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "·薩爾瓦多每擁有 1% 黑印掉落屬性，就使猩紅熔爐上限提高 0.15% 最大生命。"
  },
  AwakerTalent_57336_TalentName_1 = {
    Text = "伊始之處"
  },
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "·阿格里帕自身、裝備的命輪與密契每提供 1% 黑印掉落屬性，就使「蒼白的庇佑」的基礎護盾提高 0.5%，基礎中毒提高 1%。"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "·菲茵特每擁有 1% 死亡抵抗屬性，就使「星之搖籃」和「無邊星彩」獲得的反擊提高 0.2%，「星之搖籃」的死亡抵抗上限 +2% 。"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "·希洛每擁有 1% 傷害強效屬性，「絕境求生」就使本回合內希洛造成的傷害提高 0.3%。"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "·萊克擊殺敵人時獲得 5 黑印，萊克每有 1% 黑印掉落就使獲得量提高 1%，每場探索最多生效 5 次。\n·通過戰鬥獲取 50/125/250 黑印後，造物上限+1，戰鬥結束時選擇一個<C05_zaowu:「混沌的遺贈」>加入造物列表。"
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "贏家通吃"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "·在首領戰中，回合開始時及「熔燬·朵爾」釋放狂氣爆發後，獲得 1 層「終末」。「終末」至多擁有 10 層，達到 10 層時將 1 張「虛無終結」置入手中。"
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "湮滅之路"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] %，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·每條觸腕攻擊時都會使臨時觸腕傷害提高圖魯攻擊力的 [Arg3]％，每回合至多生效 [Arg4] 次。\n·當隊伍中存在其它 1/2/3 名「利莫里亞」喚醒體時，所有敵人受到的觸腕傷害提高 10％/25％/50％。"
