  AwakerTalent_74105_TalentDesc_1 = {
    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] %，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·「喧囂海洋」每消耗 1 張「腺體分裂」，奧瑞塔本場戰鬥後續造成的傷害提高  [Arg3]％ 攻擊力。首領戰中若「喧囂海洋」至少消耗了 20 張「腺體分裂」，「腺體分裂」打出和被消耗時造成的傷害次數 +1。每回合打出的前 [Arg4] 張「腺體分裂」不會添加「算力調和」。"
  },
