    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] %，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·戈利亞造成的基礎傷害提高 [Arg3]％，「巨刃之威」使戈利亞造成的最終傷害臨時提高 [Arg4]％。\n·當隊伍中存在 1/2/3 名其它「利莫里亞」喚醒體時，所有喚醒體力量獲取效果額外提高 6%/15%/30%。"
  },
