  AwakerTalent_74132_TalentDesc_1 = {
    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] %，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·法洛思造成的中毒提高 [Arg3]％。「遺失的久遠之城」回合結束時號令所有觸腕攻擊 1 次，但這些攻擊只造成 [Arg4]% 的傷害。\n·當隊伍中存在 1/2/3 名其它「利莫里亞」喚醒體時，傷害強效 +20%/50%/100％。"
  },
