  AwakerTalent_78618_TalentDesc_1 = {
    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] %，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·「苦痛救贖」施加的基礎傷害效果提高波呂克斯攻擊力的 [Arg3]％。\n·每疊加 50 層「罪印」將 1 張「聖心」置入手中。\n· 「罪印」達到 100 層後，「聖心」因第 3 次打出消耗後抽 1 張自身「技能卡」。\n·造成傷害時，「罪印」對「提燈教會」敵人的效果翻倍。"
  },
