    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] %，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·戰鬥開始時，使所有敵人承受的觸腕傷害提高 [Arg3]％，對「深海」敵人效果翻倍。「懲戒雷霆」對「深海」敵人造成的主動傷害提高 [Arg4]％。"
  },
