    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] %，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·所有喚醒體獲得的力量提高 [Arg3]％。\n·克萊門汀對「蟲族」敵人造成傷害時，對目標施加 [Arg4]％ 傷害的出血效果。克萊門汀每回合首次造成護盾或回復生命時，使「蟲族」敵人臨時失去防禦力 [Arg5]％ 的力量。"
  },
