  AwakerTalent_78911_TalentDesc_1 = {
    Text = "·該天賦僅在「星辰篇」關卡中生效。\n·該喚醒體的體質、攻擊、防禦提高 [Arg1] %，並使該喚醒體首次打出靈知覺醒後獲得 [Arg2] 點銀鑰能量。\n·誕妄·墨菲造成的傷害附加 [Arg3]％「獻祭」，「命契」對「降生儀式」的提高效果翻倍。\n·當隊伍中存在 1/2/3 名其它「利莫里亞」喚醒體時，生命上限提高 6%/15%/30％。「利莫里亞」喚醒體釋放狂氣爆發後獲得誕妄·墨菲 50%/125%/250% 防禦力的護盾，該效果每回合至多生效 1 次且不受護盾提高效果影響。"
  },
