  AwakerTalent_79211_TalentDesc_1 = {
    Text = "·克萊門汀的指令卡造成傷害後獲得 1 層「共感」。\n·克萊門汀喚醒體自身、命輪、密契每提供 1 點銀鑰充能屬性，暴擊率和暴擊傷害提高 0.35％ 。\n·超維回合開始後，移除所有敵人的「精神創傷」與「恐懼固著」。每移除所有敵人 1 層「精神創傷」就獲得 50 點銀鑰能量，每移除所有敵人 1 層「恐懼固著」就使其他喚醒體獲得 2 點狂氣。"
  },
