  AwakerTalent_83778_TalentName_1 = {Text = "餘火"},
  AwakerTalent_84132_TalentDesc_1 = {
    Text = "·奧瑞塔每有 1 點狂氣回充等級，戰鬥開始時獲得奧瑞塔攻擊力 2% 的觸腕傷害，每有 1% 暴擊率，戰鬥開始時獲得奧瑞塔攻擊力 1% 的觸腕傷害。"
  },
  AwakerTalent_84132_TalentName_1 = {
    Text = "快樂精靈"
  },
  AwakerTalent_89775_TalentDesc_1 = {
    Text = "·每回合首次打出「黑羽」時對所有敵人施加自身攻擊力840％的「侵蝕」並獲得 10 點狂氣。\n·卡斯托爾每有 1% 傷害強效就使施加的基礎「侵蝕」提高 1%。\n·戰鬥結束後，本次探索中卡斯托爾施加的「侵蝕」永久提高 20％。\n·首領戰施加的「侵蝕」翻倍。\n·卡斯托爾施加「侵蝕」後本回合自身傷害提高 5% 施加量。\n·卡斯托爾造成的傷害不會移除「侵蝕」。"
  },
  AwakerTalent_89775_TalentName_1 = {
    Text = "聖羽洗罪"
  },
  AwakerTalent_95804_TalentDesc_1 = {
    Text = "·杜勒賽因擊殺敵人或使用狂氣爆發對首領造成傷害後，獲得 1 具「殘骸」。\n·至多積攢 3 具「殘骸」。\n·「殘骸」會繼承至下場戰鬥。"
  },
